import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
WEIGHTS = {"clv": 0.3076, "peer": 0.2367, "rev5": 0.1824, "mom": 0.1794, "rev3": 0.0939}
MIN_W, MAX_W = 0.015, 0.16
last_decision = None


def rank_map(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(valid) < 2:
        return out
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / n
    return out


def project(raw):
    # Simple bounded simplex projection by iterative fixing; full investment, no cash.
    w = {s: max(float(raw.get(s, 0.0)), 1e-9) for s in UNIVERSE}
    free = set(UNIVERSE)
    fixed = {}
    for _ in range(20):
        scale = (1.0 - sum(fixed.values())) / max(sum(w[s] for s in free), 1e-12)
        changed = False
        for s in list(free):
            x = w[s] * scale
            if x < MIN_W:
                fixed[s] = MIN_W; free.remove(s); changed = True
            elif x > MAX_W:
                fixed[s] = MAX_W; free.remove(s); changed = True
        if not changed:
            for s in free: fixed[s] = w[s] * scale
            break
    total = sum(fixed.values())
    return {s: fixed.get(s, MIN_W) / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    account = get_account_dict()
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, dtype=float)
        h = np.asarray(df.high, dtype=float)
        l = np.asarray(df.low, dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[s] = (c, h, l, r, str(df.iloc[-1].date))
    if len(data) < 12:
        return
    decision = max(v[4] for v in data.values())
    # Ten trading-day cadence, approximated with a 14-calendar-day gate.
    if last_decision is not None:
        try:
            gap = (np.datetime64(decision, "D") - np.datetime64(last_decision, "D")) / np.timedelta64(1, "D")
            if gap < 14:
                return
        except Exception:
            return

    clv, peer, rev5, rev3, mom, invvol, five = {}, {}, {}, {}, {}, {}, {}
    for s, (c, h, l, r, _) in data.items():
        if len(c) < 25:
            continue
        candle = (2.0*c - h - l) / np.maximum(h-l, 1e-12)
        vol = max(float(np.std(r[-20:])), 0.008)
        clv[s] = np.mean(candle[-3:])
        five[s] = c[-1] / max(c[-6], 1e-12) - 1.0
        rev5[s] = -np.mean(r[-5:])
        rev3[s] = -np.mean(r[-3:])
        mom[s] = (c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + 0.01)
        invvol[s] = 1.0 / vol
    median5 = np.median(list(five.values()))
    peer = {s: five[s] - median5 for s in five}
    ranked = {k: rank_map(v) for k, v in [("clv", clv), ("peer", peer), ("rev5", rev5), ("mom", mom), ("rev3", rev3)]}
    score = {s: sum(WEIGHTS[k] * ranked[k].get(s, 0.5) for k in WEIGHTS) for s in UNIVERSE}

    # High-risk bearish correction: remain fully invested but favor defensive tradables.
    if "SPX" in data:
        c = data["SPX"][0]
        if c[-1] < c[-21] and c[-1] < c[-6]:
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] += 0.18
            for s in ("BTC", "ETH", "WTI"):
                score[s] = max(0.05, score[s] - 0.10)
    avg_iv = np.mean(list(invvol.values()))
    raw = {s: max(score[s], 0.01) * (0.78 + 0.22 * invvol.get(s, avg_iv) / avg_iv) for s in UNIVERSE}
    weights = project(raw)
    vals = np.array([score[s] for s in UNIVERSE])
    z = (vals - vals.mean()) / max(vals.std(), 1e-12)
    forecasts = {s: float(0.01 * z[i]) for i, s in enumerate(UNIVERSE)}
    factor_ids = ["miner_3_clv_1d", "peer_median_leadlag_5d", "short_term_reversal_5d", "miner_2_risk_adjusted_momentum_20d", "miner_2_short_reversal_3d"]
    rebalance_to_weights(weights, forecast_returns=forecasts, factor_ids=factor_ids, horizon_days=10)
    last_decision = decision

